using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;
public static class FinishDisplays19 {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit only");const string A="Assets/ShooterSurvival/Models/Chapters/Chapters45/Ch5Toon20261004";var root=GameObject.Find("Chapter45_World/DetailedMall_20261003/Scenery").transform;int plinths=0,racks=0;foreach(var floor in root.Cast<Transform>().Where(t=>t.name.StartsWith("2F ")&&t.name.Contains(" · ")||t.name.StartsWith("3F ")&&t.name.Contains(" · "))){if(floor.Find("Toon finishing displays 19")!=null)throw new Exception("Already applied");var g=new GameObject("Toon finishing displays 19").transform;g.SetParent(floor,false);int f=floor.GetComponent<Chapter45SceneryGroup>().floor;var ivory=AssetDatabase.LoadAssetAtPath<Material>(A+"/Ivory lit trim.mat");foreach(var shop in floor.Cast<Transform>().Where(t=>t.name.Contains(" storefront ")).ToArray()){if(f==3){foreach(var r in shop.GetComponentsInChildren<Renderer>().Where(r=>r.name=="Sports display plinth"))r.enabled=false;foreach(var good in shop.Cast<Transform>().Where(t=>t.name.StartsWith("RetailSneaker reused"))){var b=good.GetComponentInChildren<Renderer>().bounds;float h=b.min.y-floor.position.y;var obj=GameObject.CreatePrimitive(PrimitiveType.Cylinder);obj.name="Supported cream sports display";obj.transform.SetParent(g,false);obj.transform.position=new Vector3(b.center.x,floor.position.y+h/2,b.center.z);obj.transform.localScale=new Vector3(1.45f,h/2,1.45f);Object.DestroyImmediate(obj.GetComponent<Collider>());obj.GetComponent<Renderer>().sharedMaterial=ivory;plinths++;}}
 else{var src=shop.GetComponentsInChildren<MeshFilter>().FirstOrDefault(m=>m.name=="DetailedClothingRack");if(src==null)throw new Exception("Verified clothing rack missing");foreach(float x in new[]{-5.85f,5.85f}){var t=new GameObject("Reused TRELLIS clothing window").transform;t.SetParent(g,false);t.gameObject.AddComponent<MeshFilter>().sharedMesh=src.sharedMesh;var r=t.gameObject.AddComponent<MeshRenderer>();r.sharedMaterial=src.GetComponent<Renderer>().sharedMaterial;t.rotation=src.transform.rotation;t.localScale=src.transform.lossyScale;var b=r.bounds;var target=shop.TransformPoint(new Vector3(x,.04f,3.5f));t.position+=target-new Vector3(b.center.x,b.min.y,b.center.z);racks++;}}}
 var rr=g.GetComponentsInChildren<MeshRenderer>();int index=0;foreach(var group in rr.GroupBy(r=>r.sharedMaterial)){var m=new Mesh{indexFormat=IndexFormat.UInt32};m.CombineMeshes(group.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=g.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray());AssetDatabase.CreateAsset(m,A+"/Finished-displays-floor"+f+"-"+(index++)+".asset");var t=new GameObject("Batched finished displays").transform;t.SetParent(g,false);t.gameObject.AddComponent<MeshFilter>().sharedMesh=m;var r=t.gameObject.AddComponent<MeshRenderer>();r.sharedMaterial=group.Key;r.shadowCastingMode=ShadowCastingMode.Off;}foreach(var r in rr)Object.DestroyImmediate(r.gameObject);}
 EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{sportsPlinthsMatchedToShoeFeet=plinths,reusedAdditionalClothingRacks=racks,sourceModelsEdited=false,newColliders=0};}}
